create function public.catalog(p_slug text default null,p_store uuid default null,p_search text default '',p_limit integer default 24,p_offset integer default 0) returns jsonb language sql stable security definer set search_path='' as $$
select jsonb_build_object('stores',coalesce((select jsonb_agg(x) from (select s.id,s.name,s.street,s.city,s.state,s.zip_code,s.phone,s.timezone,m.name merchant_name,m.slug merchant_slug from public.stores s join public.merchants m on m.id=s.merchant_id where s.active and m.status='active' and (p_slug is null or m.slug=p_slug) and (p_store is null or s.id=p_store) and (s.name ilike '%'||left(p_search,120)||'%' or m.name ilike '%'||left(p_search,120)||'%') order by s.name,s.id limit greatest(1,least(p_limit,100)) offset greatest(0,p_offset))x),'[]'::jsonb),'products',coalesce((select jsonb_agg(x) from (select p.id,p.store_id,p.name,p.description,p.price_minor,p.available from public.products p join public.stores s on s.id=p.store_id join public.merchants m on m.id=s.merchant_id where p_store is not null and s.id=p_store and (p_slug is null or m.slug=p_slug) and s.active and m.status='active' and p.archived_at is null order by p.name,p.id limit greatest(1,least(p_limit,100)) offset greatest(0,p_offset))x),'[]'::jsonb)) $$;
create function public.cart_catalog(p_ids uuid[]) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(x),'[]'::jsonb) from (select p.id,p.name,p.price_minor,p.available,s.id store_id,s.name store_name,m.slug merchant_slug from public.products p join public.stores s on s.id=p.store_id join public.merchants m on m.id=s.merchant_id where p.id=any(p_ids[1:100]) and p.archived_at is null and s.active and m.status='active')x$$;
create function public.session_context() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('platform',exists(select 1 from public.platform_admins where user_id=auth.uid() and active),'membership',(select jsonb_build_object('merchant_id',m.id,'slug',m.slug,'name',m.name,'status',m.status,'role',mm.role) from public.merchant_memberships mm join public.merchants m on m.id=mm.merchant_id where mm.user_id=auth.uid() and mm.active))$$;
create function public.application_status() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not private.customer_ok() then raise exception 'FORBIDDEN'; end if; return (select jsonb_build_object('id',id,'name',name,'slug',slug,'status',status,'rejection_reason',rejection_reason) from public.merchants where applicant_id=auth.uid()); end$$;
create function public.update_profile(p_name text,p_locale text,p_theme text) returns void language plpgsql security definer set search_path='' as $$begin if not private.customer_ok() then raise exception 'FORBIDDEN'; end if; update public.profiles set display_name=trim(p_name),locale=p_locale,theme=p_theme where user_id=auth.uid(); end$$;
create function public.submit_merchant_application(p_name text,p_slug text) returns uuid language plpgsql security definer set search_path='' as $$declare mid uuid; begin if not private.is_verified() or not private.aal2() then raise exception 'FORBIDDEN'; end if; perform 1 from auth.users where id=auth.uid() for update; if exists(select 1 from public.merchant_memberships where user_id=auth.uid()) or exists(select 1 from public.platform_admins where user_id=auth.uid()) then raise exception 'CONFLICT'; end if; insert into public.merchants(name,slug,applicant_id) values(trim(p_name),p_slug,auth.uid()) returning id into mid; insert into public.merchant_memberships(merchant_id,user_id,role) values(mid,auth.uid(),'admin'); return mid; end$$;
create function public.resubmit_merchant_application(p_name text) returns void language plpgsql security definer set search_path='' as $$begin if not private.is_verified() or not private.aal2() then raise exception 'FORBIDDEN'; end if; update public.merchants set name=trim(p_name),status='pending',rejection_reason=null where applicant_id=auth.uid() and status='rejected'; if not found then raise exception 'CONFLICT'; end if; end$$;
create function public.create_merchant(p_name text,p_slug text) returns uuid language plpgsql security definer set search_path='' as $$declare mid uuid; begin perform private.require_platform(); insert into public.merchants(name,slug) values(trim(p_name),p_slug) returning id into mid; return mid; end$$;
create function public.set_merchant_status(p_id uuid,p_status public.merchant_status,p_reason text default null) returns void language plpgsql security definer set search_path='' as $$declare old_status public.merchant_status; begin perform private.require_platform(); select status into old_status from public.merchants where id=p_id for update; if not found then raise exception 'NOT_FOUND'; end if; if not ((old_status='pending' and p_status in ('active','rejected')) or (old_status='active' and p_status='suspended') or (old_status='suspended' and p_status='active')) then raise exception 'CONFLICT'; end if; if p_status='active' and not exists(select 1 from public.merchant_memberships where merchant_id=p_id and active and role='admin') then raise exception 'LAST_ADMIN_REQUIRED'; end if; if p_status='rejected' and (p_reason is null or length(trim(p_reason)) not between 2 and 500) then raise exception 'VALIDATION_ERROR'; end if; update public.merchants set status=p_status,rejection_reason=case when p_status='rejected' then trim(p_reason) else null end where id=p_id; end$$;
create function public.update_merchant_settings(p_id uuid,p_name text) returns void language plpgsql security definer set search_path='' as $$begin if not private.is_platform() then perform private.require_member(p_id,array['admin']::public.member_role[]); end if; update public.merchants set name=trim(p_name) where id=p_id; end$$;
create function public.create_invitation(p_merchant uuid,p_email text,p_role public.member_role) returns jsonb language plpgsql security definer set search_path='' as $$declare token text=encode(extensions.gen_random_bytes(32),'hex'); iid uuid; begin perform 1 from public.merchants where id=p_merchant for update; if private.is_platform() then if p_role<>'admin' or exists(select 1 from public.merchant_memberships where merchant_id=p_merchant and active) or not exists(select 1 from public.merchants where id=p_merchant and status='pending') then raise exception 'FORBIDDEN'; end if; else perform private.require_member(p_merchant,array['admin']::public.member_role[]); end if; if length(p_email)>254 or p_email !~ '^[^ @]+@[^ @]+\.[^ @]+$' then raise exception 'VALIDATION_ERROR'; end if; update public.merchant_invitations set revoked_at=now() where merchant_id=p_merchant and email=lower(trim(p_email)) and accepted_at is null and revoked_at is null; insert into public.merchant_invitations(merchant_id,email,role,token_hash) values(p_merchant,lower(trim(p_email)),p_role,encode(extensions.digest(token,'sha256'),'hex')) returning id into iid; return jsonb_build_object('id',iid,'token',token); end$$;
create function public.list_invitations(p_merchant uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not private.is_platform() then perform private.require_member(p_merchant,array['admin']::public.member_role[]); end if; return (select coalesce(jsonb_agg(x),'[]'::jsonb) from (select id,email,role,expires_at,accepted_at,revoked_at,delivery_state from public.merchant_invitations where merchant_id=p_merchant order by created_at desc limit 100)x); end$$;
create function public.revoke_invitation(p_id uuid) returns void language plpgsql security definer set search_path='' as $$declare mid uuid; begin select merchant_id into mid from public.merchant_invitations where id=p_id; if not private.is_platform() then perform private.require_member(mid,array['admin']::public.member_role[]); end if; update public.merchant_invitations set revoked_at=now() where id=p_id and accepted_at is null; end$$;
create function public.accept_invitation(p_token text) returns text language plpgsql security definer set search_path='' as $$declare inv public.merchant_invitations; slug text; begin if not private.is_verified() or not private.aal2() then raise exception 'FORBIDDEN'; end if; select * into inv from public.merchant_invitations where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') for update; if not found or inv.expires_at<now() or inv.accepted_at is not null or inv.revoked_at is not null or inv.email<>(select lower(email) from auth.users where id=auth.uid()) then raise exception 'FORBIDDEN'; end if; perform 1 from auth.users where id=auth.uid() for update; perform 1 from public.merchants where id=inv.merchant_id and status in ('active','pending') for update; if not found then raise exception 'FORBIDDEN'; end if; if exists(select 1 from public.merchant_memberships where user_id=auth.uid()) then raise exception 'CONFLICT'; end if; insert into public.merchant_memberships(merchant_id,user_id,role) values(inv.merchant_id,auth.uid(),inv.role); update public.merchant_invitations set accepted_at=now() where id=inv.id; select m.slug into slug from public.merchants m where id=inv.merchant_id; return slug; end$$;
create function public.change_member(p_id uuid,p_role public.member_role,p_active boolean) returns void language plpgsql security definer set search_path='' as $$declare mm public.merchant_memberships; begin select * into mm from public.merchant_memberships where id=p_id; perform private.require_member(mm.merchant_id,array['admin']::public.member_role[]); perform 1 from public.merchants where id=mm.merchant_id for update; select * into mm from public.merchant_memberships where id=p_id for update; if mm.role='admin' and mm.active and (p_role<>'admin' or not p_active) and (select count(*) from public.merchant_memberships where merchant_id=mm.merchant_id and role='admin' and active)<=1 then raise exception 'LAST_ADMIN_REQUIRED'; end if; update public.merchant_memberships set role=p_role,active=p_active where id=p_id; end$$;
create function public.create_store(p_merchant uuid,p_name text,p_street text,p_city text,p_state text,p_zip_code text,p_phone text,p_timezone text,p_active boolean default true) returns uuid language plpgsql security definer set search_path='' as $$declare sid uuid; begin perform 1 from public.merchants where id=p_merchant for update; perform private.require_member(p_merchant,array['admin','staff']::public.member_role[]); insert into public.stores(merchant_id,name,street,city,state,zip_code,phone,timezone,active) values(p_merchant,trim(p_name),trim(p_street),trim(p_city),trim(p_state),trim(p_zip_code),p_phone,p_timezone,p_active) returning id into sid; return sid; end$$;
create function public.update_store(p_id uuid,p_version integer,p_name text,p_street text,p_city text,p_state text,p_zip_code text,p_phone text,p_timezone text,p_active boolean) returns void language plpgsql security definer set search_path='' as $$declare mid uuid; begin select merchant_id into mid from public.stores where id=p_id; perform 1 from public.merchants where id=mid for update; perform private.require_member(mid,array['admin','staff']::public.member_role[]); update public.stores set name=trim(p_name),street=trim(p_street),city=trim(p_city),state=trim(p_state),zip_code=trim(p_zip_code),phone=p_phone,timezone=p_timezone,active=p_active where id=p_id and version=p_version; if not found then raise exception 'CONFLICT'; end if; end$$;
create function public.create_product(p_store uuid,p_name text,p_description text,p_price integer,p_available boolean default true) returns uuid language plpgsql security definer set search_path='' as $$declare mid uuid; pid uuid; begin select merchant_id into mid from public.stores where id=p_store; perform 1 from public.merchants where id=mid for update; perform private.require_member(mid,array['admin','staff']::public.member_role[]); insert into public.products(merchant_id,store_id,name,description,price_minor,available) values(mid,p_store,trim(p_name),trim(p_description),p_price,p_available) returning id into pid; return pid; end$$;
create function public.update_product(p_id uuid,p_version integer,p_name text,p_description text,p_price integer,p_available boolean) returns void language plpgsql security definer set search_path='' as $$declare mid uuid; begin select merchant_id into mid from public.products where id=p_id; perform 1 from public.merchants where id=mid for update; perform private.require_member(mid,array['admin','staff']::public.member_role[]); update public.products set name=trim(p_name),description=trim(p_description),price_minor=p_price,available=p_available where id=p_id and version=p_version and archived_at is null; if not found then raise exception 'CONFLICT'; end if; end$$;
create function public.archive_product(p_id uuid,p_version integer) returns void language plpgsql security definer set search_path='' as $$declare mid uuid; begin select merchant_id into mid from public.products where id=p_id; perform 1 from public.merchants where id=mid for update; perform private.require_member(mid,array['admin','staff']::public.member_role[]); update public.products set archived_at=now(),available=false where id=p_id and version=p_version and archived_at is null; if not found then raise exception 'CONFLICT'; end if; end$$;
create function public.set_product_availability(p_id uuid,p_version integer,p_available boolean) returns void language plpgsql security definer set search_path='' as $$declare mid uuid; begin select merchant_id into mid from public.products where id=p_id; perform 1 from public.merchants where id=mid for update; perform private.require_member(mid); update public.products set available=p_available where id=p_id and version=p_version and archived_at is null; if not found then raise exception 'CONFLICT'; end if; end$$;
